        schedule.startUtc=EventService::localInstant("2026-03-07 09:15:25.125",schedule.timeZone).value;schedule.endUtc=EventService::localInstant("2026-03-07 10:45:35.250",schedule.timeZone).value;
        TaskPatch patch;patch.schedule=FieldPatch<TaskSchedule>::set(schedule);auto saved=service.edit(task.id,task.rowVersion,patch);QVERIFY(saved.ok());task=saved.value;QCOMPARE(task.startOn,std::optional<QDate>(QDate(2026,3,7)));QCOMPARE(task.deadlineOn,task.startOn);
