        const auto shifted=service.moveToView(task.id,task.rowVersion,"upcoming",QDate(2026,11,5));QVERIFY(shifted.ok());task=shifted.value;const QTimeZone zone("America/New_York");QCOMPARE(task.schedule->startUtc.toTimeZone(zone).time(),QTime(9,15,25,125));QCOMPARE(task.schedule->endUtc.toTimeZone(zone).date(),QDate(2026,11,5));
        schedule.startUtc=EventService::localInstant("2026-03-07 02:30",schedule.timeZone).value;schedule.endUtc=EventService::localInstant("2026-03-07 03:30",schedule.timeZone).value;patch={};patch.schedule=FieldPatch<TaskSchedule>::set(schedule);saved=service.edit(task.id,task.rowVersion,patch);QVERIFY(saved.ok());task=saved.value;
