        patch={};patch.notes=FieldPatch<QString>::set("only notes");saved=service.edit(task.id,task.rowVersion,patch);QVERIFY(saved.ok());task=saved.value;QCOMPARE(task.startOn,std::optional<QDate>(QDate(2026,10,24)));QCOMPARE(task.deadlineOn,std::optional<QDate>(QDate(2026,11,2)));const auto visible=QueryService::select({task},"all",clock.localToday()).first();QCOMPARE(visible.startOn,std::optional<QDate>(QDate(2026,10,25)));QCOMPARE(visible.deadlineOn,std::optional<QDate>(QDate(2026,10,27)));QVERIFY(CalendarService::unscheduled({task}).isEmpty());
        patch={};patch.remindAtUtc=FieldPatch<QString>::clear();patch.reminderRepeat=FieldPatch<QString>::set("NONE");patch.schedule=FieldPatch<TaskSchedule>::set(schedule);saved=service.edit(task.id,task.rowVersion,patch);QVERIFY(saved.ok());task=saved.value;QVERIFY(task.remindAtUtc.isEmpty());QCOMPARE(task.schedule->alertMinutes,-1);QCOMPARE(task.startOn,visible.startOn);QCOMPARE(task.deadlineOn,visible.deadlineOn);
        const auto audit=repo.editHistory(task.id).value.first().toMap().value("summary").toString();QVERIFY(audit.contains("2026-10-24"));QVERIFY(audit.contains("2026-11-02"));QVERIFY(audit.contains("2026-10-25"));QVERIFY(audit.contains("2026-10-27"));
